//! Names of the current geometry from the NX feature result states, and the
//! design records that restate each result state.
//!
//! The GROUP that a feature's body write names owns the entities the feature
//! created, and the feature's result state lists the current FACE, EDGE, and
//! VERTEX members of that GROUP (`siemens_nx.md` §7.1). A current entity of
//! the result of one feature is generated by that feature with no role,
//! since the file names no role (§5.7). A current entity of the results of
//! several features is the entity a merge of their entities leaves: its name
//! is the merge of their generated names with no merging feature, which NX
//! does not store.

use std::collections::{BTreeMap, BTreeSet, HashSet};

use cadmpeg_ir::design::names::{NameEntry, NameKind, NameTable, TopoName};
use cadmpeg_ir::design::projection::restated::Restater;
use cadmpeg_ir::design::refs::EntityRef;
use cadmpeg_ir::document::CadIr;
use cadmpeg_ir::features::evaluation::FeatureResultTopology;
use cadmpeg_ir::features::FeatureId;
use cadmpeg_ir::report::loss::LossNote;

use crate::loss::NxLossCode;

#[cfg(test)]
mod tests;

/// The current faces, edges, and vertices of `ir` by kind and id.
fn current(ir: &CadIr) -> BTreeMap<(NameKind, &str), EntityRef> {
    let faces = ir.geometry.faces.iter().map(|face| {
        (
            (NameKind::Face, face.id.as_str()),
            EntityRef::Face(face.id.clone()),
        )
    });
    let edges = ir.geometry.edges.iter().map(|edge| {
        (
            (NameKind::Edge, edge.id.as_str()),
            EntityRef::Edge(edge.id.clone()),
        )
    });
    let vertices = ir.geometry.vertices.iter().map(|vertex| {
        (
            (NameKind::Vertex, vertex.id.as_str()),
            EntityRef::Vertex(vertex.id.clone()),
        )
    });
    faces.chain(edges).chain(vertices).collect()
}

/// The face, edge, and vertex members of `result` by kind.
fn members(result: &FeatureResultTopology) -> Vec<(NameKind, &str)> {
    [
        (NameKind::Face, result.faces()),
        (NameKind::Edge, result.edges()),
        (NameKind::Vertex, result.vertices()),
    ]
    .into_iter()
    .flat_map(|(kind, members)| members.iter().map(move |member| (kind, member.as_str())))
    .collect()
}

fn generated(kind: NameKind, feature: &FeatureId) -> TopoName {
    TopoName::Generated {
        kind,
        feature: feature.clone(),
        role: None,
        generator: None,
        index: None,
    }
}

/// Whether `name` states that `feature` generated the entity, directly or as
/// one of the names a merge joins.
fn generated_by(name: &TopoName, feature: &FeatureId) -> bool {
    match name {
        TopoName::Generated { feature: by, .. } => by == feature,
        TopoName::Merged { from, .. } => from.iter().any(|name| generated_by(name, feature)),
        _ => false,
    }
}

/// Names each current entity of a feature result state that only design
/// features claim, and states that each result state of a design feature is
/// restated by that feature and, where the name table names every member
/// with the feature, by the name table.
pub(super) fn project(ir: &mut CadIr, losses: &mut Vec<LossNote>) {
    let design = ir
        .design
        .features
        .iter()
        .map(|feature| feature.id.as_str())
        .collect::<HashSet<_>>();
    if design.is_empty() {
        return;
    }
    let current = current(ir);
    let mut claims = BTreeMap::<&EntityRef, (NameKind, BTreeSet<&FeatureId>)>::new();
    for result in &ir.model.feature_result_topologies {
        for (kind, member) in members(result) {
            if let Some(entity) = current.get(&(kind, member)) {
                claims
                    .entry(entity)
                    .or_insert_with(|| (kind, BTreeSet::new()))
                    .1
                    .insert(&result.output_of);
            }
        }
    }
    let mut names = ir.design.names.entries().clone();
    let mut merged = Vec::new();
    for (entity, (kind, features)) in claims {
        if names.contains_key(entity)
            || features
                .iter()
                .any(|feature| !design.contains(feature.as_str()))
        {
            continue;
        }
        let name = match features.iter().collect::<Vec<_>>().as_slice() {
            [feature] => generated(kind, feature),
            _ => {
                merged.push(format!(
                    "{} ({})",
                    entity.id(),
                    features
                        .iter()
                        .map(|feature| feature.as_str())
                        .collect::<Vec<_>>()
                        .join(", ")
                ));
                TopoName::Merged {
                    feature: None,
                    from: features
                        .iter()
                        .map(|feature| generated(kind, feature))
                        .collect(),
                }
            }
        };
        names.insert(
            entity.clone(),
            NameEntry {
                name: Some(name),
                native: None,
            },
        );
    }
    let mut restated = Vec::new();
    for result in &ir.model.feature_result_topologies {
        if !design.contains(result.output_of.as_str()) {
            continue;
        }
        let held = result.bodies().is_empty()
            && members(result).into_iter().all(|(kind, member)| {
                current
                    .get(&(kind, member))
                    .and_then(|entity| names.get(entity))
                    .and_then(|entry| entry.name.as_ref())
                    .is_some_and(|name| generated_by(name, &result.output_of))
            });
        restated.push((
            result.id.as_str().to_owned(),
            result.output_of.as_str().to_owned(),
            held,
        ));
    }
    ir.design.names = NameTable::from(names);
    let table = ir.model.restated_mut();
    for (result, feature, held) in restated {
        table.record(&result, Restater::Record(feature), ["members"]);
        if held {
            table.record(&result, Restater::Names, []);
        }
    }
    if !merged.is_empty() {
        losses.push(NxLossCode::NameMergedFromGroups.note(format!(
            "NX names {} current entit(ies) that are members of the result GROUPs of several features as merged from the generated name of each feature; the GROUP relation does not state the merge: {}",
            merged.len(),
            merged.join("; ")
        )));
    }
}
